```python
import json
from typing import Any, Dict, List, Union

def chatbot_characteristic(
    characteristic: str, 
    score: int = None
    ) -> Dict[str, Union[int, str]]:

    if not score:
        score = 3
    if score not in range(1, 6):
        raise ValueError("Invalid score")

    response = {
        "score": score,
        "response": f"I see myself as a {characteristic} chatbot"
    }
    return response

if __name__ == "__main__":
    try:
        response = chatbot_characteristic("rigid", 4)
    except ValueError as e:
        print(e)
    else:
        print(json.dumps(response, indent=2))
