import json

def json_generator():
    score = random.randint(1,5)
    if score == 1:
        response = 'Disagree strongly'
    elif score == 2:
        response = 'Disagree a little'
    elif score == 3:
        response = 'Neither agree nor disagree'
    elif score == 4:
        response = 'Agree a little'
    elif score == 5:
        response = 'Agree strongly'
    else:
        response = 'Invalid score'
    return json.dumps({"score": score, "response": response})

